 public MainWindow(){InitializeComponent();var buildPath=Environment.ProcessPath??System.Reflection.Assembly.GetExecutingAssembly().Location;var buildTime=File.GetLastWriteTime(buildPath);Title=$"Dragon's Den Visual WorldForge | DEFAULT Foundation5R7R40 | TEST CompleteZoneIR | Build {buildTime:yyyy-MM-dd HH:mm}";DdvwfTitleText.Text=Title;Viewport.CoreWebView2InitializationCompleted+=(_,e)=>{if(!e.IsSuccess)StatusText.Text=$"Renderer failed: {e.InitializationException?.Message}";};var root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DragonsDen","DDVWF");_workspace=new(Path.Combine(root,"workspace.json"));Loaded+=async(_,_)=>await RestoreAsync();Closing+=async(_,_)=>{if(_compass is not null)_settings.Windows["Compass"]=new DDVWF.Core.Workspace.WindowState(_compass.Left,_compass.Top,_compass.Width,_compass.Height,_compass.WindowState==System.Windows.WindowState.Minimized);await PersistAsync();};PreviewKeyDown+=ShortcutKeyDown;}
